#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>

using namespace std;

char gridA[12][12], gridB[12][12];
int sizeN, maxT;
bool visitedDP[70][12][12][12][12];
bool reachable[12][12][12][12];
int timeMap[12][12];

void exploreDP(int tStep, int x, int y, int x0, int y0) {
    if (maxT >= 70 || x < 0 || x >= sizeN || y < 0 || y >= sizeN)
        return;
    if (gridA[x][y] < '0' || gridA[x][y] > '9')
        return;
    if (tStep > maxT + 1)
        return;
    if (visitedDP[tStep][x][y][x0][y0])
        return;
    if (timeMap[x][y] != 0 && tStep > timeMap[x][y])
        return;
    if (timeMap[x][y] == tStep && (gridB[x][y] > '9' || gridB[x][y] <= '0'))
        return;
    visitedDP[tStep][x][y][x0][y0] = true;

    if (tStep < timeMap[x][y]) {
        exploreDP(tStep + 1, x, y, x0, y0);
        exploreDP(tStep + 1, x + 1, y, x0, y0);
        exploreDP(tStep + 1, x - 1, y, x0, y0);
        exploreDP(tStep + 1, x, y + 1, x0, y0);
        exploreDP(tStep + 1, x, y - 1, x0, y0);
    }
}

int main() {
    int n, t;
    cin >> n >> t;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> gridA[i][j];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> gridB[i][j];

    vector<vector<int>> graph;
    vector<int> E(210, 0), H(210, 0);
    int C[210][210] = {0};
    int pN[11][11] = {0};

    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            timeMap[i][j] = -1;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] == 'Z') {
                timeMap[i][j] = 0;
                q.push({i, j});
            }

    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};

    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (timeMap[p.first][p.second] >= t) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d], nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n && gridA[ni][nj] >= '0' && gridA[ni][nj] <= '9' && timeMap[ni][nj] == -1) {
                timeMap[ni][nj] = timeMap[p.first][p.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (timeMap[i][j] == -1)
                timeMap[i][j] = t;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] >= '0' && gridA[i][j] <= '9')
                exploreDP(0, i, j, i, j);

    vector<int> startNode;
    graph.push_back(startNode);

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++)
                    for (int nt = 0; nt <= t; nt++)
                        reachable[i1][j1][i2][j2] |= visitedDP[nt][i1][j1][i2][j2];

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (gridA[i1][j1] > '0' && gridA[i1][j1] <= '9') {
                int k = graph.size();
                vector<int> g;
                graph.push_back(g);
                E[k] = gridA[i1][j1] - '0';

                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9')
                            if (reachable[i2][j2][i1][j1]) {
                                int _k;
                                if (pN[i2][j2] == 0) {
                                    vector<int> _g;
                                    _k = graph.size();
                                    graph.push_back(_g);
                                    pN[i2][j2] = _k;
                                } else {
                                    _k = pN[i2][j2];
                                }
                                graph[k].push_back(_k);
                                graph[_k].push_back(k);
                                C[k][_k] = 10000;
                                C[_k][k] = 0;
                            }
            }

    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && pN[i2][j2] > 0) {
                int _k = pN[i2][j2];
                graph[_k].push_back(0);
                C[_k][0] = gridB[i2][j2] - '0';
                C[0][_k] = 0;
            }

    while (true) {
        bool allDone = true;
        for (int i = 1; i < (int)graph.size(); i++) {
            while (E[i] > 0) {
                bool progress = true;
                int minH = 10000;
                for (int jIdx : graph[i]) {
                    if (C[i][jIdx] - E[i] > 0 && H[i] == H[jIdx] + 1) {
                        int delta = min(C[i][jIdx] - E[i], E[i]);
                        F[i][jIdx] += delta;
                        F[jIdx][i] -= delta;
                        E[i] -= delta;
                        E[jIdx] += delta;
                        progress = false;
                        allDone = false;
                        if (E[i] == 0) break;
                    }
                    minH = min(minH, H[jIdx]);
                }
                if (H[i] != minH + 1 && minH != 10000)
                    H[i] = minH + 1;
                if (progress) break;
            }
        }
        if (allDone) break;
    }

    cout << E[0] << endl;
    return 0;
}
